12	public class ResettableSystemProperties implements AutoCloseable {
13	
14	    private final Map<String, String> toRestore;
15	
16	    public ResettableSystemProperties(Map<String, String> toSet) {
17	        Objects.requireNonNull(toSet);
18	        if (toSet.isEmpty()) {
19	            toRestore = Collections.emptyMap();
20	            return;
21	        }
22	        toRestore = new HashMap<>();
23	        for (var entry : toSet.entrySet()) {
24	            String oldValue = System.setProperty(entry.getKey(), entry.getValue());
25	            toRestore.put(entry.getKey(), oldValue);
26	        }
27	    }
