34	        return new ResettableSystemProperties(Collections.emptyMap());
35	    }
36	
37	    @Override
38	    public void close() {
39	        for (var entry : toRestore.entrySet()) {
40	            if (entry.getValue() != null) {
41	                System.setProperty(entry.getKey(), entry.getValue());
42	            } else {
43	                System.clearProperty(entry.getKey());
44	            }
45	        }
46	    }
