1	package io.quarkus.liquibase.runtime;
2	
3	import java.util.Locale;
4	import java.util.function.Function;
5	
6	import javax.sql.DataSource;
7	
8	import jakarta.enterprise.inject.UnsatisfiedResolutionException;
9	
10	import io.quarkus.agroal.runtime.DataSources;
11	import io.quarkus.agroal.runtime.UnconfiguredDataSource;
12	import io.quarkus.arc.Arc;
13	import io.quarkus.arc.InstanceHandle;
14	import io.quarkus.arc.SyntheticCreationalContext;
15	import io.quarkus.datasource.common.runtime.DataSourceUtil;
16	import io.quarkus.liquibase.LiquibaseFactory;
17	import io.quarkus.runtime.ResettableSystemProperties;
18	import io.quarkus.runtime.RuntimeValue;
19	import io.quarkus.runtime.annotations.Recorder;
20	import liquibase.Liquibase;
21	import liquibase.lockservice.LockServiceFactory;
22	
23	@Recorder
24	public class LiquibaseRecorder {
25	
26	    private final RuntimeValue<LiquibaseRuntimeConfig> config;
27	
28	    public LiquibaseRecorder(RuntimeValue<LiquibaseRuntimeConfig> config) {
29	        this.config = config;
30	    }
31	
32	    public Function<SyntheticCreationalContext<LiquibaseFactory>, LiquibaseFactory> liquibaseFunction(String dataSourceName) {
33	        return new Function<SyntheticCreationalContext<LiquibaseFactory>, LiquibaseFactory>() {
34	            @Override
35	            public LiquibaseFactory apply(SyntheticCreationalContext<LiquibaseFactory> context) {
36	                DataSource dataSource;
37	                try {
38	                    dataSource = context.getInjectedReference(DataSources.class).getDataSource(dataSourceName);
39	                    if (dataSource instanceof UnconfiguredDataSource) {
40	                        throw DataSourceUtil.dataSourceNotConfigured(dataSourceName);
41	                    }
42	                } catch (RuntimeException e) {
43	                    throw new UnsatisfiedResolutionException(String.format(Locale.ROOT,
44	                            "Unable to find datasource '%s' for Liquibase: %s",
45	                            dataSourceName, e.getMessage()), e);
46	                }
47	
48	                LiquibaseFactoryProducer liquibaseProducer = context.getInjectedReference(LiquibaseFactoryProducer.class);
49	                return liquibaseProducer.createLiquibaseFactory(dataSource, dataSourceName);
50	            }
51	        };
52	    }
53	
54	    public void doStartActions(String dataSourceName) {
55	        if (!config.getValue().enabled) {
56	            return;
57	        }
58	        // Liquibase is active when the datasource itself is active.
59	        if (!Arc.container().instance(DataSources.class).get().getActiveDataSourceNames().contains(dataSourceName)) {
60	            return;
61	        }
62	
63	        InstanceHandle<LiquibaseFactory> liquibaseFactoryHandle = LiquibaseFactoryUtil.getLiquibaseFactory(dataSourceName);
64	        try {
65	            LiquibaseFactory liquibaseFactory = liquibaseFactoryHandle.get();
66	            var config = liquibaseFactory.getConfiguration();
67	            if (!config.cleanAtStart && !config.migrateAtStart) {
68	                return;
69	            }
70	            try (Liquibase liquibase = liquibaseFactory.createLiquibase();
71	                    ResettableSystemProperties resettableSystemProperties = liquibaseFactory
72	                            .createResettableSystemProperties()) {
73	                if (config.cleanAtStart) {
74	                    liquibase.dropAll();
75	                }
76	                if (config.migrateAtStart) {
77	                    var lockService = LockServiceFactory.getInstance()
78	                            .getLockService(liquibase.getDatabase());
79	                    lockService.waitForLock();
80	                    try {
81	                        if (config.validateOnMigrate) {
82	                            liquibase.validate();
83	                        }
84	                        liquibase.update(liquibaseFactory.createContexts(), liquibaseFactory.createLabels());
85	                    } finally {
86	                        lockService.releaseLock();
87	                    }
88	                }
89	            }
90	        } catch (UnsatisfiedResolutionException e) {
91	            //ignore, the DS is not configured
92	        } catch (Exception e) {
93	            throw new IllegalStateException("Error starting Liquibase", e);
94	        }
95	    }
96	
97	}
